import re

# For each dialog, separate agent messages and customer messages
# Then check for apologies in agent messages and complaints in customer messages

def get_agent_messages(dialog, company_id):
    """Extract agent (company) messages from dialog"""
    lines = dialog.split('\n\n')
    agent_msgs = []
    for line in lines:
        if line.strip().startswith(company_id):
            agent_msgs.append(line)
    return agent_msgs

def get_customer_messages(dialog, company_id):
    """Extract customer messages from dialog"""
    lines = dialog.split('\n\n')
    customer_msgs = []
    for line in lines:
        if not line.strip().startswith(company_id) and line.strip():
            customer_msgs.append(line)
    return customer_msgs

def has_apology(agent_messages):
    """Check if any agent message contains an apology"""
    apology_keywords = ['sorry', 'apologize', 'apologies', 'apology', 'apologise', 'regret']
    text = ' '.join(agent_messages).lower()
    return any(kw in text for kw in apology_keywords)

